const catalogs = { en, fr, es };
export function language(value?: string): keyof typeof catalogs {
  const code = value?.toLowerCase().split(/[-_]/, 1)[0];
  return code && Object.hasOwn(catalogs, code) ? code as keyof typeof catalogs : "en";
}
export function translate(key: TranslationKey, locale?: string): string {
  return catalogs[language(locale)][key] ?? en[key];
}
